/* habit_det.c — Phase 11 step 71b (KESSHO §4.3–§4.4; DECISIONS_10 #6): THE
 * CRYSTAL DROP'S THEOREM AND THE CLEAVAGE PROFILES, in closed form. Strict C11,
 * no core link: the maps are deform.glsl's, transcribed line for line.
 *
 * The drop: in the action-angle frame about the centre (ρ = r²/2, θ; dx∧dy =
 * dρ∧dθ) the v2 drop is ρ_src = ρ − r₀²/2; with any habit profile R(θ) > 0 it is
 * ρ_src = ρ − R(θ)²/2, θ_src = θ — a kick generated by V(θ) = R(θ)²/2, exact for
 * any R(θ) at any amplitude (J = [[1, −RR′], [0, 1]], det J = 1). This test
 * takes the Cartesian map P → P_src = C + rel·√(1 − R²/r²) exactly as the shader
 * writes it, finite-differences its Jacobian at 10⁴ random (θ, roundness) per
 * habit, and asks |det J − 1| < 1e-6 — away from the corner rays at roundness
 * 0, where R′ jumps (the crease is the point: J jumps there by design).
 * Also: each ray is bijective (r_src monotone in r), and the interior
 * coordinate r / R(θ) is the homothety the rings follow.
 *
 * The tines: a shear P_src = P − m·D̂·g(d) by a function of the perpendicular
 * distance alone is exact for any profile; the three shipped profiles are
 * BUMPS — g(d) = 0 for d ≥ H = 4α and g continuous — the fix that keeps zero
 * fabrication (the first draft's monotone ramp, profile 3, is the fault). */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>

static int fails = 0, checks = 0;
#define CHECK(c, ...) do { checks++; if (!(c)) { fails++; fprintf(stderr, "FAIL %s:%d: ", __FILE__, __LINE__); fprintf(stderr, __VA_ARGS__); fputc('\n', stderr); } } while (0)

static double lse2(double a, double b, double k) { double m = a > b ? a : b; return m + log(exp(k * (a - m)) + exp(k * (b - m))) / k; }
static double lse3(double a, double b, double c, double k) { double m = a > b ? (a > c ? a : c) : (b > c ? b : c); return m + log(exp(k * (a - m)) + exp(k * (b - m)) + exp(k * (c - m))) / k; }

/* deform.glsl's habit_R, in doubles */
static double habit_R(int habit, double r0, double roundness, double blades, double angle, double theta) {
    if (habit == 0) return r0;
    double t = theta - angle;
    double k = 2.0 + 40.0 * (1.0 - roundness) * (1.0 - roundness);
    double R;
    if (habit == 1) { const double A = 1.3631; R = r0 / lse2(fabs(sin(t)), fabs(sin(t - A)), k); }
    else if (habit == 2) R = r0 / lse3(fabs(cos(t)), fabs(cos(t - 1.0471976)), fabs(cos(t - 2.0943951)), k);
    else { double m = blades < 2.0 ? 2.0 : blades; double c = cos(m * t), c2 = c * c, c8 = c2 * c2 * c2 * c2; R = r0 * (1.0 + 0.6 * c8) / (1.0 + 0.6 * 0.2734375); }
    return R + (r0 - R) * roundness;
}
/* the drop's outside branch: P_src for P (centre at the origin, aspect 1) */
static void drop_map(int habit, double r0, double roundness, double blades, double angle, double x, double y, double* xs, double* ys) {
    double dist = sqrt(x * x + y * y);
    double R = habit_R(habit, r0, roundness, blades, angle, atan2(y, x));
    double f = sqrt(1.0 - (R * R) / (dist * dist));
    *xs = x * f; *ys = y * f;
}
static double drop_det(int habit, double r0, double roundness, double blades, double angle, double x, double y, double h) {
    double ax, ay, bx, by, cx, cy, dx, dy;
    drop_map(habit, r0, roundness, blades, angle, x + h, y, &ax, &ay);
    drop_map(habit, r0, roundness, blades, angle, x - h, y, &bx, &by);
    drop_map(habit, r0, roundness, blades, angle, x, y + h, &cx, &cy);
    drop_map(habit, r0, roundness, blades, angle, x, y - h, &dx, &dy);
    double j11 = (ax - bx) / (2 * h), j21 = (ay - by) / (2 * h), j12 = (cx - dx) / (2 * h), j22 = (cy - dy) / (2 * h);
    return j11 * j22 - j12 * j21;
}
/* the corner rays of the hard polygons (where R′ jumps at roundness 0) */
static int near_corner(int habit, double angle, double theta, double wedge) {
    double t = theta - angle;
    if (habit == 1) {   /* the rhomb's corners: where |sin t| = |sin(t − A)| → t = A/2 + kπ/2 */
        for (int k = -4; k <= 4; k++) { double c = 1.3631 / 2.0 + k * M_PI / 2.0; double d = fabs(remainder(t - c, 2.0 * M_PI)); if (d < wedge) return 1; }
    } else if (habit == 2) {   /* the hexagon's: t = 30° + k·60° */
        for (int k = -8; k <= 8; k++) { double c = M_PI / 6.0 + k * M_PI / 3.0; double d = fabs(remainder(t - c, 2.0 * M_PI)); if (d < wedge) return 1; }
    }
    return 0;
}
static double frand(void) { return (double)rand() / (double)RAND_MAX; }

/* deform.glsl's tine profiles, g(d) for the signed distance ys (H = 4α) */
static double tine_g(int profile, double alpha, double ys) {
    double d = fabs(ys);
    if (profile == 0) return alpha / (alpha + d);
    double H = 4.0 * alpha, u = d / H;
    if (profile == 1) return u < 1.0 / 3.0 ? 1.0 : (u < 1.0 ? (1.0 - u) * 1.5 : 0.0);
    if (profile == 2) { double v = 1.0 - u; if (v < 0.0) v = 0.0; if (v > 1.0) v = 1.0; return v - sin(25.132741 * v) / 25.132741; }
    double g = ys / alpha; return g < -1.0 ? -1.0 : (g > 1.0 ? 1.0 : g);   /* 3: the fault — monotone, unwindowed */
}

int main(void) {
    srand(71);
    const double r0 = 0.12;
    /* 1. det J = 1 for every habit at 10⁴ random (θ, roundness, r > R) — the rhomb and the hexagon away from the corner rays at roundness 0 */
    for (int habit = 0; habit < 4; habit++) {
        double worst = 0.0; long n = 0;
        for (int i = 0; i < 10000; i++) {
            double roundness = (i % 4 == 0) ? 0.0 : frand();   /* a quarter of the draws at the hard polygon */
            double theta = frand() * 2.0 * M_PI, angle = frand() * 2.0 * M_PI, blades = 2.0 + floor(frand() * 11.0);
            double R = habit_R(habit, r0, roundness, blades, angle, theta);
            double r = R * (1.05 + 2.0 * frand());           /* outside the habit, up to 3 R (the rim itself is the singular pre-image, as the v2 drop's) */
            if (roundness < 0.05 && near_corner(habit, angle, theta, 0.02)) continue;   /* the corner rays at roundness 0: taken below */
            double det = drop_det(habit, r0, roundness, blades, angle, r * cos(theta), r * sin(theta), 1e-7);
            double e = fabs(det - 1.0); if (e > worst) worst = e; n++;
        }
        CHECK(worst < 1e-6, "habit %d: max |det J - 1| = %.3e over %ld points", habit, worst, n);
        printf("[habit_det] habit %d: max |det J - 1| = %.2e over %ld random points (roundness 0..1, every angle)\n", habit, worst, n);
    }
    /* 2. the crease: the theorem holds ON the corner ray too (det J = 1 at roundness 0 where R turns fastest), and the corner's
          angular curvature there is the crease — an order of magnitude sharper at roundness 0 than at 0.5, zero at 1 (the circle) */
    {
        const double thc = 1.3631 / 2.0, rc = 2.5 * r0;   /* the rhomb's corner lies at R = r0 / sin(A/2) = 1.59 r0: probe beyond it */
        double det0 = drop_det(1, r0, 0.0, 5.0, 0.0, rc * cos(thc), rc * sin(thc), 1e-7);
        double det1 = drop_det(1, r0, 1.0, 5.0, 0.0, rc * cos(thc), rc * sin(thc), 1e-7);
        CHECK(fabs(det0 - 1.0) < 1e-6 && fabs(det1 - 1.0) < 1e-6, "on the corner ray: det %.8f at roundness 0, %.8f at roundness 1 — the theorem holds where R turns fastest", det0, det1);
        const double dth = 1e-3;
        double c0 = (habit_R(1, r0, 0.0, 5.0, 0.0, thc + dth) - 2.0 * habit_R(1, r0, 0.0, 5.0, 0.0, thc) + habit_R(1, r0, 0.0, 5.0, 0.0, thc - dth)) / (dth * dth);
        double c5 = (habit_R(1, r0, 0.5, 5.0, 0.0, thc + dth) - 2.0 * habit_R(1, r0, 0.5, 5.0, 0.0, thc) + habit_R(1, r0, 0.5, 5.0, 0.0, thc - dth)) / (dth * dth);
        double c1 = (habit_R(1, r0, 1.0, 5.0, 0.0, thc + dth) - 2.0 * habit_R(1, r0, 1.0, 5.0, 0.0, thc) + habit_R(1, r0, 1.0, 5.0, 0.0, thc - dth)) / (dth * dth);
        CHECK(fabs(c0) > 5.0 * fabs(c5) && fabs(c1) < 1e-9, "the crease: |R''| at the corner %.1f at roundness 0, %.1f at 0.5 (> 5x), %.1e at 1 (the circle)", fabs(c0), fabs(c5), fabs(c1));
        printf("[habit_det] the crease: the corner's angular curvature |R''| = %.1f at roundness 0, %.1f at 0.5, %.1e at 1; det J = 1 on the ray at every roundness\n", fabs(c0), fabs(c5), fabs(c1));
    }
    /* 3. bijective ray by ray: r_src monotone in r outside R, and every point outside maps outside the centre */
    for (int habit = 1; habit < 4; habit++) {
        int mono = 1;
        for (int i = 0; i < 2000 && mono; i++) {
            double theta = frand() * 2.0 * M_PI, roundness = frand();
            double R = habit_R(habit, r0, roundness, 5.0, 0.3, theta), last = -1.0;
            for (int k = 1; k <= 200; k++) {
                double r = R * (1.0 + 2.0 * k / 200.0), xs, ys;
                drop_map(habit, r0, roundness, 5.0, 0.3, r * cos(theta), r * sin(theta), &xs, &ys);
                double rs = sqrt(xs * xs + ys * ys);
                if (rs <= last) mono = 0;
                last = rs;
            }
        }
        CHECK(mono, "habit %d: r_src monotone along every ray", habit);
    }
    /* 4. the homothety: the interior coordinate r / R(θ) — the ring at fraction f is the habit scaled by f (the shader's radial = dist / R) */
    {
        double worst = 0.0;
        for (int i = 0; i < 2000; i++) {
            double theta = frand() * 2.0 * M_PI, f = 0.2 + 0.7 * frand();
            double R = habit_R(1, r0, 0.0, 5.0, 0.0, theta);
            double r = f * R;                                   /* a point on the ring 'f' */
            double e = fabs(r / R - f); if (e > worst) worst = e;
        }
        CHECK(worst < 1e-12, "the ring at fraction f sits at r = f R(θ): max error %.2e", worst);
    }
    /* 5. the tine profiles: 0–2 are bumps (zero at and beyond H = 4α, continuous), 3 is the monotone fault; every profile's shear has det J = 1 */
    {
        const double alpha = 0.05, H = 4.0 * alpha;
        for (int prof = 1; prof <= 2; prof++) {
            CHECK(tine_g(prof, alpha, H) == 0.0 && tine_g(prof, alpha, 1.5 * H) == 0.0 && tine_g(prof, alpha, -2.0 * H) == 0.0, "profile %d is zero at and beyond H", prof);
            double jump = 0.0;
            for (int k = 0; k < 4000; k++) { double y = -1.2 * H + 2.4 * H * k / 4000.0, dy = 2.4 * H / 4000.0; double j = fabs(tine_g(prof, alpha, y + dy) - tine_g(prof, alpha, y)); if (j > jump) jump = j; }
            CHECK(jump < 0.01, "profile %d is continuous (max step %.4f over 4000 samples)", prof, jump);
        }
        CHECK(tine_g(1, alpha, 0.2 * H) == 1.0 && tine_g(1, alpha, 0.5 * H) > 0.5 && tine_g(1, alpha, 0.5 * H) < 1.0, "the twin kink: flat at 1 inside the lamella, linear to 0 beyond H/3");
        CHECK(fabs(tine_g(2, alpha, 0.0) - (1.0 - sin(25.132741) / 25.132741)) < 1e-9, "the terrace: four flat steps from the line (stair(1) at d = 0)");
        CHECK(tine_g(3, alpha, 2.0 * H) == 1.0 && tine_g(3, alpha, -2.0 * H) == -1.0, "the fault (3): unwindowed — ±1 far from the line, the half-planes displaced against each other (what fabricates)");
        CHECK(tine_g(0, alpha, 0.0) == 1.0 && fabs(tine_g(0, alpha, H) - 0.2) < 1e-12, "Jaffer's profile is the v2 tine: 1 at the line, α/(α + d) beyond");
        /* the shear's determinant: P_src = P − m D g(y) with y the perpendicular distance (unchanged by the shear) → det J = 1 for any g */
        for (int prof = 0; prof <= 3; prof++) {
            double worst = 0.0;
            for (int i = 0; i < 2000; i++) {
                double y = -1.5 * H + 3.0 * H * frand(), x = frand(), m = 0.1, h = 1e-6;
                /* D = (1, 0): x_src = x − m g(y), y_src = y */
                double j11 = 1.0, j12 = -m * (tine_g(prof, alpha, y + h) - tine_g(prof, alpha, y - h)) / (2 * h), j21 = 0.0, j22 = 1.0;
                double det = j11 * j22 - j12 * j21; (void)x;
                double e = fabs(det - 1.0); if (e > worst) worst = e;
            }
            CHECK(worst < 1e-12, "profile %d: the shear's det J = 1 (max |det - 1| %.2e)", prof, worst);
        }
    }
    printf("[habit_det] %d/%d checks passed\n", checks - fails, checks);
    return fails;
}
